internal static class TestImportIsolation {
 internal static string Phase="isolation";
 internal static void SetPhase(string value){Phase=value;}
 internal static void Require(bool value,string message){if(!value)throw new InvalidOperationException(message);}
 internal static string SetDataRoot(){
  string app=Path.GetFullPath(Common.AppRoot),configured=Environment.GetEnvironmentVariable("LOCALWALLPAPER_TEST_DATA_ROOT");
  string data=DataLocation.SafePath(configured);string expected=Path.Combine(app,"tests");
  if(!DataLocation.Same(data,expected))throw new InvalidDataException("导入测试数据根必须精确指向本次隔离程序tests目录");
  string marker=Path.Combine(app,".localwallpaper-test-root");if(!File.Exists(marker)||File.ReadAllText(marker).Trim()!="wallpaper-small-trial-20261103|local_trial_import_flow_r13_20261105")throw new InvalidDataException("导入测试隔离标记不匹配");
  string expectedImage=Path.GetFullPath(Path.Combine(app,"build"))+Path.DirectorySeparatorChar;
  if(!Path.GetFullPath(Application.ExecutablePath).StartsWith(expectedImage,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("导入测试映像不在本次隔离build目录");
  Directory.CreateDirectory(expected);LocalImport.NoLinks(app);LocalImport.NoLinks(expected);Common.Root=data;Directory.CreateDirectory(Common.Root);return Common.Root;
 }
}

internal static class ImportFlowSmoke {
 internal static int Run(string evidence){
  ControlWindow owner=null;int code=1;var context=new ApplicationContext();var dispatch=new System.Windows.Forms.Timer{Interval=1};
  dispatch.Tick+=async(s,e)=>{dispatch.Stop();try{TestImportIsolation.SetDataRoot();Common.SaveNew(evidence+".started.json",new{image=Application.ExecutablePath,phase="isolation-root-validated"});owner=new ControlWindow(null,0,null);await owner.RunImportFlowSmoke(evidence);Common.SaveNew(evidence+".completed.json",new{phase="smoke-method-returned",mainReportExists=File.Exists(evidence)});if(!File.Exists(evidence))throw new InvalidDataException("导入smoke返回但没有写成功报告");code=0;}catch(Exception ex){try{Common.SaveNew(evidence,new{schemaVersion=1,passed=false,phase=TestImportIsolation.Phase,error=ex.ToString(),scope="TEST_BUILD-only actual import handlers and worker; no playback, no external UI automation"});}catch{}code=1;}finally{try{if(owner!=null){owner.TestStopImportSmokeTimers();owner.Dispose();}}catch{}dispatch.Dispose();context.ExitThread();}};
  dispatch.Start();
  Application.Run(context);
  return code;
 }
 internal static int Reopen(string evidence){
  try{TestImportIsolation.SetDataRoot();string catalog=Path.Combine(Common.Root,"data","catalog.json");TestImportIsolation.Require(File.Exists(catalog),"新进程缺少隔离登记文件");var library=new WallpaperLibrary();TestImportIsolation.Require(library.Error==null&&library.Doc.Items.Count==1,"新进程没有恰好读取到一个导入登记");var item=library.Doc.Items.Single();TestImportIsolation.Require(item.OriginKind=="official-local-import"&&item.PreviewConfirmedSha256==null&&item.DesktopConfirmedSha256==null,"导入登记错误继承播放或桌面确认");TestImportIsolation.Require(LocalImport.Under(item.SourcePath,Path.Combine(Common.Root,"library"))&&File.Exists(item.SourcePath),"新进程资源路径没有落在隔离管理库");TestImportIsolation.Require(LocalImport.Under(item.CoverPath,Path.Combine(Common.Root,"library"))&&File.Exists(item.CoverPath),"新进程封面没有落在隔离管理库");string hash=V3Package.HashFile(item.SourcePath);TestImportIsolation.Require(hash==item.RegisteredSha256,"新进程回读资源哈希不一致");var receipt=Common.Read(item.SourceRecordPath);var receiptCandidate=Common.Obj(receipt["Candidate"]);TestImportIsolation.Require(Common.S(receipt,"Sha256")==hash&&Common.S(receiptCandidate,"Id")==item.ResourceId&&LocalImport.Under(Common.S(receiptCandidate,"Source"),Path.Combine(Common.AppRoot,"tests","fixture-source")),"新进程来源登记关系不一致");TestImportIsolation.Require(library.Selected!=null&&library.Selected.Id==item.Id&&library.Status(item)=="已导入 · 播放未验证","首页重开状态或选择项不一致");Common.SaveNew(evidence,new{schemaVersion=1,passed=true,method="fresh TEST_BUILD process",catalogItems=library.Doc.Items.Count,itemId=item.Id,resourceId=item.ResourceId,registeredSha256=hash,managedResource=item.SourcePath,managedCover=item.CoverPath,origin=item.OriginKind,previewConfirmationPresent=false,desktopConfirmationPresent=false,status=library.Status(item),playerStarted=false,desktopChanged=false});return 0;}catch(Exception ex){try{Common.SaveNew(evidence,new{schemaVersion=1,passed=false,error=ex.ToString(),method="fresh TEST_BUILD process"});}catch{}return 1;}
 }
}

