 static byte[] Deflate(byte[] bytes){using(var output=new MemoryStream()){using(var stream=new DeflateStream(output,CompressionMode.Compress,true))stream.Write(bytes,0,bytes.Length);return output.ToArray();}}
 static byte[] EncryptRaw(byte[] bytes){byte[] password=Encoding.ASCII.GetBytes("123"),s,key,iv,m;using(var h=SHA256.Create())s=h.ComputeHash(password);using(var h=MD5.Create()){m=h.ComputeHash(password);key=h.ComputeHash(s.Concat(m).ToArray());iv=h.ComputeHash(s);}using(var aes=Aes.Create()){aes.Key=key;aes.IV=iv;aes.Mode=CipherMode.CBC;aes.Padding=PaddingMode.PKCS7;using(var encryptor=aes.CreateEncryptor())return encryptor.TransformFinalBlock(bytes,0,bytes.Length);}}
 static byte[] Encrypt(byte[] bytes){return EncryptRaw(Deflate(bytes));}
 static byte[] Png(){return Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+/lN8AAAAASUVORK5CYII=");}
 static byte[] Table(uint offset,uint previewStored,uint payloadOffset,uint payloadStored){using(var memory=new MemoryStream())using(var w=new BinaryWriter(memory,Encoding.UTF8,true)){w.Write((uint)2);WriteEntry(w,offset,previewStored,"preview.png");WriteEntry(w,payloadOffset,payloadStored,"sample.bin");w.Flush();return memory.ToArray();}}
 static void WriteEntry(BinaryWriter w,uint offset,uint stored,string name){byte[] n=Encoding.UTF8.GetBytes(name);w.Write(offset);w.Write(stored);w.Write((uint)0);w.Write((uint)n.Length);w.Write(n);}
 static byte[] Fixture(){byte[] preview=Encrypt(Png()),payload=new byte[1024*1024];uint state=314159;
  for(int i=0;i<payload.Length;i++){state=state*1664525+1013904223;payload[i]=(byte)(state>>24);}byte[] body=Encrypt(payload);byte[] tableStored=null;uint tableSize=0;uint first=0,second=0;
  for(int attempt=0;attempt<8;attempt++){first=checked(16u+tableSize);second=checked(first+(uint)preview.Length);byte[] table=EncryptRaw(Table(first,(uint)preview.Length,second,(uint)body.Length));if(table.Length==tableSize){tableStored=table;break;}tableSize=(uint)table.Length;tableStored=table;}
  first=checked(16u+(uint)tableStored.Length);second=checked(first+(uint)preview.Length);tableStored=EncryptRaw(Table(first,(uint)preview.Length,second,(uint)body.Length));if(first!=16u+(uint)tableStored.Length)throw new InvalidDataException("隔离CWP-v2目录长度未收敛");uint total=checked(16u+(uint)tableStored.Length+(uint)preview.Length+(uint)body.Length);
  using(var output=new MemoryStream())using(var w=new BinaryWriter(output)){w.Write(0x02505743u);w.Write(total);w.Write((uint)tableStored.Length);w.Write((uint)0);w.Write(tableStored);w.Write(preview);w.Write(body);w.Flush();return output.ToArray();}
 }
  void PrepareFixture(out string source,out ImportCandidate candidate){string fixtureRoot=Path.Combine(Common.AppRoot,"tests","fixture-source");Directory.CreateDirectory(Path.Combine(fixtureRoot,"cache_info"));Directory.CreateDirectory(Path.Combine(fixtureRoot,"wallpaper","wpcache","dynamic"));byte[] bytes=Fixture();string md5;using(var h=MD5.Create())md5=BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();source=Path.Combine(fixtureRoot,"wallpaper","wpcache","dynamic",md5+".cwp");File.WriteAllBytes(source,bytes);var recordObject=new{wpId=730013,wpName=md5+".cwp",wpMd5=md5,wpType=2};byte[] record=Encoding.UTF8.GetBytes("0000"+Common.Json.Serialize(recordObject));for(int i=0;i<record.Length;i++)record[i]^=0xe7;File.WriteAllBytes(Path.Combine(fixtureRoot,"cache_info","730013_fixture.dat"),record);File.WriteAllText(Path.Combine(Common.Root,"tests","import-root.txt"),fixtureRoot);string names=Path.Combine(Common.Root,"tests","name-cache-empty");Directory.CreateDirectory(names);File.WriteAllText(Path.Combine(Common.Root,"tests","name-cache-root.txt"),names);string saved=SourceLocation.SaveRoot(fixtureRoot);TestImportIsolation.Require(DataLocation.Same(saved,fixtureRoot),"自选来源配置未写入隔离来源");candidate=LocalImport.ReadRecord(Path.Combine(fixtureRoot,"cache_info","730013_fixture.dat"));TestImportIsolation.Require(candidate!=null&&candidate.Status.StartsWith("可导入"),"来源候选没有按已知记录/目录规则发现");}
