    phase="duplicate-import-transaction";TestImportIsolation.SetPhase(phase);dialog.Dispose();dialog=new ImportDialog(this);await dialog.Scan();row=dialog.list.Items[0];candidate=(ImportCandidate)row.Tag;TestImportIsolation.Require(CandidateChecks.Passed(candidate),"已导入候选重新检查未通过");var duplicateResult=await ImportJob("copy",candidate,null);bool duplicateImport;var duplicateItem=RegisterImport(importOperation,duplicateResult,out duplicateImport);TestImportIsolation.Require(duplicateImport&&library.Doc.Items.Count==1&&cards.Controls.Count==1&&duplicateItem.Id==item.Id,"重复导入没有保持单一登记卡片");steps.Add(new{step="duplicate",passed=true,catalogItems=library.Doc.Items.Count,cards=cards.Controls.Count,duplicate=duplicateImport,registrationId=duplicateItem.Id});
